class Solution {
  public int numberOfSubmatrices(char[][] grid) {
    int rows = grid.length, cols = grid[0].length;
    int[] x = new int[cols];
    int[] y = new int[cols];
    int answer = 0;
    for (int r = 0; r < rows; r++) {
      int rowX = 0, rowY = 0;
      for (int c = 0; c < cols; c++) {
        if (grid[r][c] == 'X') rowX++;
        else if (grid[r][c] == 'Y') rowY++;
        x[c] += rowX;
        y[c] += rowY;
        if (x[c] == y[c] && x[c] > 0) answer++;
      }
    }
    return answer;
  }
}
